import traceback

# pragma pylint: disable=unnecessary-pass
# ------------------------------------ Generic ------------------------------------


class AbstractUeLibException(Exception):
    """To allow for catching all exceptions raised in this library."""
    pass

# ------------------------------------ Alias related ------------------------------------


class UnknownAlias(AbstractUeLibException):
    """Ue alias is unknown."""
    pass


class WrongAlias(AbstractUeLibException):
    """Alias is wrong"""
    pass


class AliasAlreadyAssignedError(AbstractUeLibException):
    """Alias is already Assigned."""
    def __init__(self, alias, assigned_object):
        """
        Basic initialization.

        :param alias:
        :param assigned_object:
        """
        super(AliasAlreadyAssignedError, self).__init__()
        self.alias = alias
        self.assigned_object = assigned_object  # TODO use it for global aliases testing (if alias4ue is DT used alias)

    def __str__(self):
        err = f"alias '{self.alias}' already assigned to '{self.assigned_object}'"
        return err


