# ------------------------------------ Message query ------------------------------------
class MessageQuerySyntaxError(AbstractUeLibException):
    """Message Query syntax error"""
    def __init__(self, syntax_err_value, line, column, whole_query):
        """
        Basic initialization.

        :param syntax_err_value:
        :param line:
        :param column:
        :param whole_query:
        """
        super(MessageQuerySyntaxError, self).__init__()
        self.syntax_err_value = syntax_err_value
        self.line = line
        self.column = column
        self.pointing_line = (' ' * (column - 1)) + '^'
        self.whole_query = whole_query

    def __str__(self):
        coordinated_query = self._compose_coordinated_query()
        err = f"{self.syntax_err_value} (line {self.line}, column {self.column}):\n{coordinated_query}"
        return err

    def _numbered_columns(self):
        ten_steps_line = '         1         2         3         4         5         6         7         8         9         0' * 10
        numbered_columns_line = ten_steps_line[0:self.column + 1 + 10].rstrip()
        return numbered_columns_line

    def _numbered_lines(self):
        lines = []
        for index, line in enumerate(self.whole_query.splitlines()):
            numbered_line = f"{index + 1:>3}|{line}"
            lines.append(numbered_line)
        return lines

    def _compose_coordinated_query(self):
        """Build query with columns and lines coordinates"""
        lines = ["{:>3}|{}".format('', self._numbered_columns())]
        for index, numbered_line in enumerate(self._numbered_lines()):
            line_nb = index + 1
            lines.append(numbered_line)
            if line_nb == self.line:
                lines.append("{:>3}|{}".format('', self.pointing_line))
        return "\n".join(lines)


class MessageQueryTokenizerError(MessageQuerySyntaxError):
    """Message Query tokenizer error."""
    def __init__(self, illegal_character, line, column, token_in_line, whole_query):
        """
        Basic initialization.

        :param illegal_character:
        :param line:
        :param column:
        :param token_in_line:
        :param whole_query:
        """
        self.illegal_character = illegal_character
        self.token_in_line = token_in_line
        syntax_err_value = f"Illegal character '{self.illegal_character}'"
        super(MessageQueryTokenizerError, self).__init__(syntax_err_value, line, column, whole_query)


class MessageQueryParserError(MessageQuerySyntaxError):
    """Message Query parser error"""
    def __init__(self, token_value, line, column, whole_query):
        """
        Basic initialization.

        :param token_value:
        :param line:
        :param column:
        :param whole_query:
        """
        self.token_value = token_value
        if self.token_value is not None:
            syntax_err_value = f"Wrong syntax near '{self.token_value}'"
            super(MessageQueryParserError, self).__init__(syntax_err_value, line, column, whole_query)

    def __str__(self):
        if self.token_value is None:
            return "Syntax error at End Of Query"
        return super(MessageQueryParserError, self).__str__()


class FunctionNotReturningBoolean(AbstractUeLibException):
    """Function not returning boolean"""
    def __init__(self, message_query_function, return_value):
        """
        Basic initialization.

        :param message_query_function:
        :param return_value:
        """
        super(FunctionNotReturningBoolean, self).__init__()
        self.message_query_function = message_query_function
        self.return_value = return_value

    def __str__(self):
        err = f"Function '{self.message_query_function.__name__}()' should return {type(True)} and not {type(self.return_value)}"
        return err


class ComparingNonListAgainstListOfQuery(AbstractUeLibException):
    """Comparing non-List against list of query"""
    def __init__(self, structure, query_list):
        """
        Basic initialization.

        :param structure:
        :param query_list:
        """
        super(ComparingNonListAgainstListOfQuery, self).__init__()
        self.structure = structure
        self.query_list = query_list

    def __str__(self):
        err = f"Field selector with type: {type(self.structure)} cannot be compared to {type(self.query_list)}"
        return err


class MessageQueryFunctionAlreadyExists(AbstractUeLibException):
    """MessageQuery function already exists"""
    def __init__(self, message_query_function):
        """
        Basic initialization.

        :param message_query_function:
        """
        super(MessageQueryFunctionAlreadyExists, self).__init__()
        self.message_query_function = message_query_function

    def __str__(self):
        err = f"Message verifier with name {self.message_query_function} already registered in global scope"
        return err


class FunctionWithTooFewParameters(AbstractUeLibException):
    """Function with too few parameters"""
    def __init__(self, function):
        """
        Basic initialization.

        :param function:
        """
        super(FunctionWithTooFewParameters, self).__init__()
        self.function = function

    def __str__(self):
        err = f"Function '{self.function.__name__}' must have at least one parameter (message part it operates on)"
        return err


class UnknownFunction(AbstractUeLibException):
    """Function is unknown."""
    def __init__(self, function_name):
        """
        Basic initialization.

        :param function_name:
        """
        super(UnknownFunction, self).__init__()
        self.function_name = function_name

    def __str__(self):
        err = f"Function '{self.function_name}' should be registered via @function_on_field_value or @function_on_value decorator"
        return err


class FunctionFail(AbstractUeLibException):
    """Function fail."""
    def __init__(self, function_raised_exception, function):
        """
        Basic initialization.

        :param function_raised_exception:
        :param function:
        """
        super(FunctionFail, self).__init__()
        self.function_raised_exception = function_raised_exception
        self.function = function
        self.stacktrace = traceback.format_exc()

    def __str__(self):
        err = (f"Function '{self.function.__name__}' failed because of:\n"
               f"{self.function_raised_exception.__class__.__name__}: {self.function_raised_exception}")
        return err + "\n" + self.stacktrace


