class RequiredDeviceNotFound(AbstractUeLibException):
    """Cannot find device that matches requirements."""
    def __init__(self, device_characteristics):
        """
        Basic initialization.

        :param device_characteristics:
        """
        super(RequiredDeviceNotFound, self).__init__()
        self.device_characteristics = device_characteristics

    def __str__(self):
        return f'Cannot find Device that matches requirements: {str(self.device_characteristics)}'


