class PoolCreationError(AbstractUeLibException):
    """Unknown device."""
    pass


class UnknownDevicePoolPackage(AbstractUeLibException):
    """Unknown Device Pool package."""
    def __init__(self, module_name_of_pool, class_name_of_pool):
        """
        Basic initialization.

        :param module_name_of_pool:
        :param class_name_of_pool:
        """
        super(UnknownDevicePoolPackage, self).__init__()
        self.module_name_of_pool = module_name_of_pool
        self.class_name_of_pool = class_name_of_pool

    def __str__(self):
        err = f"Can't determine package for {self.module_name_of_pool}.{self.class_name_of_pool}"
        err += "\n  expected format of pool-type: <prefix>Device<suffix>"
        err += "\n  example: SomeDevicePool (maps to ute_common_abstract_core.device.some.somedevicepool.SomeDevicePool)"
        return err


